std::vector<Polygon2d> result;
for (auto it = arr.faces_begin(); it != arr.faces_end(); ++it) {
    if (!it->is_unbounded()) {
        Polygon2d polygon;
        auto ccb = it->outer_ccb();
        do {
            polygon.push_back(ccb->source()->point());
            ++ccb;
        } while (ccb != it->outer_ccb());
        result.push_back(polygon);
    }
}
return result;

